CREATE TABLE "Settlement" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"ledgerId" UUID NOT NULL,"planId" UUID,"fromUserId" UUID NOT NULL,"toUserId" UUID NOT NULL,"amountMinor" BIGINT NOT NULL,"currency" VARCHAR(3) NOT NULL,"note" TEXT,"settledAt" TIMESTAMPTZ(3) NOT NULL,"createdById" UUID NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"voidedAt" TIMESTAMPTZ(3),CONSTRAINT "Settlement_pkey" PRIMARY KEY("id"),CONSTRAINT "Settlement_amount_positive_check" CHECK("amountMinor">0),CONSTRAINT "Settlement_distinct_users_check" CHECK("fromUserId"<>"toUserId"));
CREATE TABLE "ExpenseSplitOffset" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"expenseSplitId" UUID NOT NULL,"amountMinor" BIGINT NOT NULL,"createdById" UUID NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"voidedAt" TIMESTAMPTZ(3),CONSTRAINT "ExpenseSplitOffset_pkey" PRIMARY KEY("id"),CONSTRAINT "ExpenseSplitOffset_amount_positive_check" CHECK("amountMinor">0));
CREATE INDEX "Settlement_ledgerId_idx" ON "Settlement"("ledgerId"); CREATE INDEX "Settlement_planId_idx" ON "Settlement"("planId"); CREATE INDEX "Settlement_fromUserId_idx" ON "Settlement"("fromUserId"); CREATE INDEX "Settlement_toUserId_idx" ON "Settlement"("toUserId"); CREATE INDEX "ExpenseSplitOffset_expenseSplitId_idx" ON "ExpenseSplitOffset"("expenseSplitId"); CREATE INDEX "ExpenseSplitOffset_createdById_idx" ON "ExpenseSplitOffset"("createdById");
ALTER TABLE "Settlement" ADD CONSTRAINT "Settlement_ledgerId_fkey" FOREIGN KEY("ledgerId") REFERENCES "Ledger"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Settlement" ADD CONSTRAINT "Settlement_planId_fkey" FOREIGN KEY("planId") REFERENCES "Plan"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Settlement" ADD CONSTRAINT "Settlement_fromUserId_fkey" FOREIGN KEY("fromUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Settlement" ADD CONSTRAINT "Settlement_toUserId_fkey" FOREIGN KEY("toUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Settlement" ADD CONSTRAINT "Settlement_createdById_fkey" FOREIGN KEY("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ExpenseSplitOffset" ADD CONSTRAINT "ExpenseSplitOffset_expenseSplitId_fkey" FOREIGN KEY("expenseSplitId") REFERENCES "ExpenseSplit"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ExpenseSplitOffset" ADD CONSTRAINT "ExpenseSplitOffset_createdById_fkey" FOREIGN KEY("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
